import math


class Circle:
    def __init__(self, r):
        self.r = r

    def area(self):
        return math.pi * self.r ** 2


class Rectangle:
    def __init__(self, w, h):
        self.w = w
        self.h = h

    def area(self):
        return self.w * self.h


def total_area(shapes):
    return sum((s.area() for s in shapes), 0.0)


print(total_area([Rectangle(4, 6), Rectangle(6, 12)]))

def describe(obj):
    if hasattr(obj, 'describe'):
        return obj.describe()
    return 'no description'


class Apple:
    def describe(self):
        return 'A red apple'


print(describe(Apple()))
